css:
* { box-sizing: border-box; }
#root * { text-transform: uppercase; }
button, a { touch-action: manipulation; }
.app { min-height: 100%; }
.screen { max-width: var(--app-width); margin: 0px auto; padding: 0 var(--app-gutter) calc(var(--space-6) + env(safe-area-inset-bottom)); }
.stack { display: flex; flex-direction: column; gap: var(--stack-gap); }
.stack--loose { --stack-gap: var(--space-4); }
.stack--section { --stack-gap: var(--space-section); }
.segmented { display: flex; flex-wrap: wrap; }
.segmented .segmented__btn { --btn-fill: var(--surface-card); --btn-edge: var(--border-stamped); --btn-ink: var(--text-heading); --btn-fill-hover: var(--surface-inset); --btn-edge-hover: var(--border-stamped); min-height: var(--tap-min); padding: 0 var(--space-3h); border-width: var(--bw-heavy); border-radius: 0px; font-size: var(--fs-ui); }
.segmented .segmented__btn + .segmented__btn { margin-left: calc(var(--bw-heavy) * -1); }
.segmented .segmented__btn[aria-pressed="true"] { background: var(--text-heading); border-color: var(--border-stamped); color: var(--text-on-ink); }
.segmented .segmented__btn[aria-pressed="true"]::before { content: none; }
.segmented .segmented__btn:focus-visible { position: relative; z-index: 1; }
@media (forced-colors: active) {
.segmented .segmented__btn[aria-pressed="true"] { background: highlight; color: highlighttext; }
}
.btn { --btn-fill: var(--surface-card); --btn-edge: var(--border-rule); --btn-ink: var(--text-body); --btn-fill-hover: var(--surface-inset); --btn-edge-hover: var(--text-caption); display: inline-flex; align-items: center; justify-content: center; gap: var(--space-1h); min-height: var(--tap-min); padding: var(--space-2) var(--space-4); border: var(--bw-rule) solid var(--btn-edge); border-radius: var(--radius-sm); background: var(--btn-fill); color: var(--btn-ink); font-family: var(--font-display); font-size: var(--fs-ui); letter-spacing: var(--ls-label); line-height: var(--lh-compact); text-align: center; text-decoration: none; text-transform: uppercase; cursor: pointer; transition: transform var(--dur-fast) var(--ease-stamp),
    background-color var(--dur-fast) var(--ease-standard),
    border-color var(--dur-fast) var(--ease-standard); }
.btn:active { transform: translate(var(--bw-heavy), var(--bw-heavy)); }
.btn[aria-pressed="true"], .btn[aria-current="page"] { background: var(--accent-primary); border-color: var(--accent-primary); color: var(--text-on-ink); }
.btn[aria-pressed="true"]::before, .btn[aria-current="page"]::before { content: "✓" / ""; flex: 0 0 auto; line-height: var(--lh-solid); }
.btn:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--bw-heavy); }
.btn:disabled, .btn[aria-disabled="true"] { opacity: var(--opacity-disabled); cursor: default; }
@media (prefers-reduced-motion: reduce) {
.btn, .btn__icon { transition: none; }
.btn:active { transform: none; }
}
@media (prefers-reduced-motion: reduce) {
* { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}
.flipback :is(.pill, .btn, .hlclip, .hlclip__frame, .hlclip__play, .flipback__potgShotwrap, .plink) { border-radius: 0px; }
@media (min-width: 740px) {
.screen { max-width: 960px; }
}
.ledger tbody td { border-top-width: medium; border-top-style: none; border-top-color: currentcolor; }
.ledger tbody tr { background-image: linear-gradient(var(--border-hairline), var(--border-hairline)); background-repeat: no-repeat; background-position: left top; background-size: 100% var(--bw-hair); }
.ledger thead th { font-weight: var(--w-semibold); }
.ledger .lft { text-align: left; }
.ledger .yr { color: var(--text-heading); font-weight: var(--w-bold); }
.ledger .ledger__label { color: var(--text-muted); font-family: var(--font-body); }
.ledger tr.is-allstar td { background: rgba(233, 195, 63, 0.16); }
.ledger tr.is-allstar .yr { color: var(--clay-deep); }
.ledger__allstar { color: var(--clay); margin-left: 3px; font-size: var(--fs-caption); }
.ledger tfoot td { border-top: var(--bw-rule) solid var(--border-rule); background: var(--bg-page); font-family: var(--font-mono); font-variant-numeric: tabular-nums; font-weight: var(--w-bold); color: var(--text-heading); }
.ledger tfoot .yr { font-family: var(--font-display); text-transform: uppercase; letter-spacing: var(--ls-caps); font-size: var(--fs-label); color: var(--text-caption); }
@media (max-width: 739.98px) {
.ledger .col-narrow-hide { display: none; }
.ledger { --table-cell: var(--space-1h) var(--space-1h); }
}
.pnext__page { padding-top: var(--space-4); }
.pnext__section { padding-top: var(--space-3h); }
.playernext .pnext__section { flex-flow: wrap; container-type: inline-size; }
.pnext__section > .pnext__slot { flex: 1 1 100%; min-width: 0px; }
.pnext__slot { margin-top: var(--space-3h); }
.seasonmod__bar, .seasonmod__foot { justify-content: space-between; }
.seasonmod__caption { color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-label); }
.seasonmod__tiles { display: grid; grid-template-columns: repeat(5, minmax(0px, 1fr)); gap: var(--space-2); }
.seasonmod__tile.stattile { padding: var(--space-2) var(--space-1); text-align: center; }
.seasonmod__tile .stattile__value { font-size: var(--fs-hero-sm); }
@media (min-width: 740px) {
.seasonmod__tile.stattile { padding: var(--space-3h) var(--space-2); }
.seasonmod__tile .stattile__value { font-size: var(--fs-hero-xl); }
}
.seasonmod .ledger thead th { background: var(--surface-card); border-bottom: var(--bw-heavy) solid var(--border-stamped); font-weight: var(--w-bold); letter-spacing: var(--ls-label); }
@media (min-width: 740px) {
.seasonmod .ledger tbody td, .seasonmod .ledger tfoot td { font-size: var(--fs-body); }
}
.seasonmod .ledger .ledger__label { font-family: var(--font-mono); }
.seasonmod .ledger tfoot .yr { font-size: var(--fs-label); }
.seasonmod .ledger tfoot td { background: var(--surface-card); border-top: var(--bw-heavy) solid var(--border-stamped); }
.seasonmod__war { position: relative; padding: 0 var(--space-1); border: 0px; background: transparent; color: inherit; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; font-size: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; line-height: var(--lh-tight); cursor: pointer; }
.seasonmod__war::after { content: ""; position: absolute; inset: calc(-1 * var(--space-3)) calc(-1 * var(--space-1)); }
.seasonmod__war:hover, .seasonmod__war:focus-visible, .seasonmod__war[aria-expanded="true"] { background: var(--surface-stamped-tint); }
.seasonmod__foot { color: var(--text-caption); font-family: var(--font-mono); font-size: var(--fs-cell); line-height: var(--lh-loose); }
.seasonmod__link { min-height: var(--space-10); padding: 0 var(--space-1); border: 0px; background: none; color: var(--text-heading); font-family: var(--font-display); font-size: var(--fs-label); font-weight: var(--w-bold); letter-spacing: var(--ls-caps); text-transform: uppercase; text-decoration: underline; text-underline-offset: var(--space-1); cursor: pointer; }
.seasonmod__link:focus-visible { outline: var(--bw-heavy) solid var(--focus-ring); outline-offset: var(--bw-heavy); }
@media (hover: hover) {
.logtable__grid tbody tr:not(.logtable__div, :has(a, button)):hover { background: var(--surface-row-hover); }
}
